import { useMemo, useState } from 'react';
import { Table, Tag, Pagination } from '@jinx-ui/react';

interface User {
  id: string;
  name: string;
  role: string;
  status: 'active' | 'disabled';
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const UsersTable: React.FC<UsersTableProps> = ({ users }) => {
  const [page, setPage] = useState(1);

  const totalPages = Math.max(1, Math.ceil(users.length / PAGE_SIZE));

  const pageUsers = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, page]);

  return (
    <div className="jx-stack jx-gap-md">
      <Table.Root>
        <Table.Header>
          <Table.Row>
            <Table.HeadCell>Имя</Table.HeadCell>
            <Table.HeadCell>Роль</Table.HeadCell>
            <Table.HeadCell>Статус</Table.HeadCell>
          </Table.Row>
        </Table.Header>
        <Table.Body>
          {pageUsers.map((user) => (
            <Table.Row key={user.id}>
              <Table.Cell>{user.name}</Table.Cell>
              <Table.Cell>{user.role}</Table.Cell>
              <Table.Cell>
                {user.status === 'active' ? (
                  <Tag color="success">Активен</Tag>
                ) : (
                  <Tag color="neutral">Отключён</Tag>
                )}
              </Table.Cell>
            </Table.Row>
          ))}
        </Table.Body>
      </Table.Root>

      <Pagination
        className="jx-flex jx-justify-center"
        page={page}
        totalPages={totalPages}
        onPageChange={setPage}
      />
    </div>
  );
};

export default UsersTable;

